import json
from collections import deque, Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    cnt=Counter(x for r in grid for x in r)
    bg=cnt.most_common(1)[0][0]
    out=[r[:] for r in grid]
    seen=[[False]*w for _ in range(h)]
    def comp(i,j):
        c=grid[i][j]; cells=[]; dq=deque([(i,j)]); seen[i][j]=True
        while dq:
            y,x=dq.popleft(); cells.append((y,x))
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx]==c:
                    seen[ny][nx]=True; dq.append((ny,nx))
        return c,set(cells)
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg and not seen[i][j]:
                c,cells=comp(i,j)
                reach=[[False]*w for _ in range(h)]; dq=deque()
                for x in range(w):
                    for y in (0,h-1):
                        if (y,x) not in cells and not reach[y][x]: reach[y][x]=True; dq.append((y,x))
                for y in range(h):
                    for x in (0,w-1):
                        if (y,x) not in cells and not reach[y][x]: reach[y][x]=True; dq.append((y,x))
                while dq:
                    y,x=dq.popleft()
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not reach[ny][nx] and (ny,nx) not in cells:
                            reach[ny][nx]=True; dq.append((ny,nx))
                interior=[(y,x) for y in range(h) for x in range(w) if not reach[y][x] and (y,x) not in cells]
                if interior:
                    fill=7 if (len(interior)%2==1 or len(interior)<=9) else 2
                    for y,x in interior: out[y][x]=fill
    return out

